/**
 * Base64-embedded Hind Regular/Bold TTFs (SIL OFL 1.1 — see Hind-OFL.txt in
 * this directory), generated from google/fonts' ofl/hind sources. Embedded
 * as JS string constants rather than read from disk at runtime: Vercel's
 * output file tracer has twice already dropped asset files it didn't
 * statically detect a route needing (@sparticuz/chromium's bin/, see
 * ADR-015) — a string import is guaranteed to ship with the bundle, no
 * tracing rule to get wrong. Hind was chosen over Noto Sans because it
 * ships one unsplit static file per weight covering full Latin + the
 * Rupee sign (U+20B9) in the same file; Noto Sans's web builds split
 * those into separate latin/devanagari subset files, and react-pdf/fontkit
 * doesn't do cross-file glyph fallback within one registered weight.
 */
export const HIND_REGULAR_TTF_BASE64 = '';
export const HIND_BOLD_TTF_BASE64 = '';
